import React from 'react';
import ReactDOM from 'react-dom/client';
import './App.css';
import App from './App';

const container = document.getElementById('root');

if (!container) {
  console.error("Failed to find the root element");
} else {
  const root = ReactDOM.createRoot(container);
  root.render(
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );
}
